155	                // line defaults to a neutral "units" (the same fallback CreateLineItem applies).
156	                Object unit = li.getOrDefault("unit", "units");
157	                jdbc.update(
158	                        "INSERT INTO invoice_line_items"
159	                                + " (id, invoice_id, description, quantity, unit, unit_price)"
160	                                + " VALUES (?, ?, ?, ?, ?, ?)",
161	                        ((Number) li.get("id")).longValue(),
162	                        ((Number) inv.get("id")).longValue(),
163	                        li.get("description"),
164	                        ((Number) li.get("qty")).intValue(),
165	                        unit.toString(),
