174	        for (Map<String, Object> pay : payments) {
175	            long paymentId = ((Number) pay.get("id")).longValue();
176	            jdbc.update(
177	                    "INSERT INTO invoice_payments (id, invoice_id, amount, paid_date)"
178	                            + " VALUES (?, ?, ?, ?)",
