200	                    ((Number) t.get("projectId")).longValue(),
201	                    t.get("title"), done);
202	        }
203	        List<Map<String, Object>> tags =
204	                (List<Map<String, Object>>) fixture.getOrDefault("tags", List.of());
205	        for (Map<String, Object> tag : tags) {
206	            jdbc.update("INSERT INTO tags (id, name) VALUES (?, ?)",
207	                    ((Number) tag.get("id")).longValue(), tag.get("name"));
208	        }
