210	        // write time so the newest-first order is deterministic. `at` is optional — a spec that
211	        // only cares a note exists leaves it out, defaulting to now().
212	        List<Map<String, Object>> notes =
213	                (List<Map<String, Object>>) fixture.getOrDefault("notes", List.of());
214	        long maxNoteId = 0;
215	        for (Map<String, Object> n : notes) {
216	            java.time.OffsetDateTime at = n.get("at") != null
217	                    ? java.time.OffsetDateTime.parse(n.get("at").toString())
218	                    : java.time.OffsetDateTime.now();
219	            long noteId = ((Number) n.get("id")).longValue();
220	            jdbc.update(
221	                    "INSERT INTO notes (id, target_type, target_id, text, created_at)"
222	                            + " VALUES (?, ?, ?, ?, ?)",
223	                    noteId,
224	                    n.get("targetType"),
225	                    ((Number) n.get("targetId")).longValue(),
226	                    n.get("text"),
227	                    at);
