231	        // next create would collide on id 1. Bump the sequence past the seeded rows so a note added
232	        // through the API gets a fresh id above them.
233	        if (maxNoteId > 0) {
234	            jdbc.execute("ALTER TABLE notes ALTER COLUMN id RESTART WITH " + (maxNoteId + 1));
235	        }
236	        // The many-to-many links: which seeded tag sits on which seeded project.
237	        List<Map<String, Object>> projectTags =
238	                (List<Map<String, Object>>) fixture.getOrDefault("projectTags", List.of());
239	        for (Map<String, Object> pt : projectTags) {
240	            jdbc.update("INSERT INTO project_tags (project_id, tag_id) VALUES (?, ?)",
241	                    ((Number) pt.get("projectId")).longValue(),
242	                    ((Number) pt.get("tagId")).longValue());
243	        }
244	    }
245	}
