9	/**
10	 * GET /api/clients/statement?clientId=&lt;id&gt; — a statement for one client: every invoice across
11	 * every project the client owns, in id order, each carrying how much is still DUE on it, plus the
12	 * TOTAL the client still owes (the sum of those dues). Scoped to a client (the statement is for one
13	 * client), so the client id arrives as a query parameter. The cross-project join and the derived
14	 * balances live on the server, computed in {@link BigDecimal} so there is no float drift — the same
15	 * derivation {@link InvoiceAmountDue} applies per invoice. Wired by
16	 * officefloor/rest/api/clients/statement.GET.yml.
17	 */
18	public class GetClientStatement {
19	
20	    public void service(@RequestParam("clientId") String clientId,
21	            ProjectRepository projects, InvoiceRepository invoices,
22	            InvoicePaymentRepository payments,
23	            ObjectResponse<ClientStatementView> response) {
24	        Long id = Long.valueOf(clientId);
25	        List<StatementInvoiceView> rows = new ArrayList<>();
26	        BigDecimal total = BigDecimal.ZERO;
27	        // The client owns projects; each project owns invoices. Walk the client's projects (id order)
28	        // and collect every invoice, so the statement puts them all in one place.
29	        for (Project project : projects.findByClientIdOrderByIdAsc(id)) {
30	            for (Invoice invoice : invoices.findByProjectIdOrderByIdAsc(project.getId())) {
31	                BigDecimal paid = payments.findByInvoiceIdOrderByIdAsc(invoice.getId()).stream()
32	                        .map(InvoicePayment::getAmount)
33	                        .reduce(BigDecimal.ZERO, BigDecimal::add);
34	                BigDecimal due = invoice.getAmount().subtract(paid);
35	                rows.add(new StatementInvoiceView(invoice.getId(), invoice.getProjectId(),
36	                        invoice.getStatus(), invoice.getAmount(), due));
37	                total = total.add(due);
38	            }
39	        }
40	        rows.sort((a, b) -> Long.compare(a.id(), b.id()));
41	        response.send(new ClientStatementView(id, rows, total));
42	    }
43	}
