public class Invoice {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "project_id", nullable = false)
    private Long projectId;

    @Column(nullable = false)
    private BigDecimal amount;

    /**
     * The lifecycle status of the invoice: DRAFT when raised, SENT once the user sends it, PAID once
     * the user takes payment. Payment is only allowed after it has been sent.
     */
    @Column(nullable = false)
    private String status;

    /** When the invoice went out. */
    @Column(name = "issued_date", nullable = false)
    private LocalDate issuedDate;

    /** When the invoice is due to be paid. */
    @Column(name = "due_date", nullable = false)
    private LocalDate dueDate;

    /**
     * The percentage taken off the invoice as a discount (0–100). The subtotal is the sum of the
     * invoice's line items; the discount is that percentage of the subtotal, and the final total is
     * the subtotal minus the discount. Defaults to zero — no discount takes nothing off
     * (V29__invoice_discount.sql).
     */
    @Column(name = "discount_pct", nullable = false)
    private BigDecimal discountPct = BigDecimal.ZERO;

    protected Invoice() {
    }

    public Invoice(Long projectId, BigDecimal amount, LocalDate issuedDate, LocalDate dueDate) {
        this.projectId = projectId;
        this.amount = amount;
        this.status = "DRAFT";
        this.issuedDate = issuedDate;
        this.dueDate = dueDate;
    }

    public Long getId() {
        return id;
    }

    public Long getProjectId() {
        return projectId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    /**
     * Set this invoice's amount to the sum of its line items. The amount is derived from the lines
     * (V15__invoice_line_items.sql), so it is recomputed and stored whenever a line is added.
     */
    public void setAmount(BigDecimal amount) {
        this.amount = amount;
    }

    public String getStatus() {
        return status;
    }

    public LocalDate getIssuedDate() {
        return issuedDate;
    }

    public LocalDate getDueDate() {
        return dueDate;
    }

    /** The percentage discount taken off this invoice's subtotal (0–100, zero when none is set). */
    public BigDecimal getDiscountPct() {
        return discountPct;
    }

    /** Send this invoice — the DRAFT -> SENT transition the send action performs. */
    public void markSent() {
        this.status = "SENT";
    }

    /** Whether this invoice has been sent, and so may be paid. */
    public boolean isSent() {
        return "SENT".equals(this.status);
    }

    /** Mark this invoice paid — the status transition the pay action performs. */
    public void markPaid() {
        this.status = "PAID";
    }

    /**
     * Void this invoice — the terminal transition the cancel action performs when an invoice was
     * sent by mistake. A VOID invoice no longer counts towards what is owed.
     */
    public void markVoid() {
        this.status = "VOID";
    }
}

package net.officefloor.hq.app;

import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.web.ObjectResponse;

/**
 * GET /api/dashboard — the home summary: the client count, the project count, the outstanding total
 * (the sum of every SENT invoice amount — money actually owed) and the overdue count (how many SENT
 * invoices are past their due date). An invoice counts towards both only once it has been sent:
 * DRAFTs have not gone out yet and PAID invoices are already settled, so both are excluded. "Overdue"
 * is measured against a reference date — the seeded {@link DashboardReference} if present (so the
 * harness is deterministic), otherwise today. A cross-entity aggregate read, so it injects the
 * repositories it needs. Wired by officefloor/rest/api/dashboard.GET.yml.
 */
public class GetDashboard {

    public void service(ClientRepository clients, ProjectRepository projects,
            InvoiceRepository invoices, DashboardReferenceRepository reference,
            ObjectResponse<DashboardView> response) {
        BigDecimal outstanding = invoices.findAll().stream()
                .filter(invoice -> "SENT".equals(invoice.getStatus()))
                .map(Invoice::getAmount)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
        LocalDate asOf = reference.findAll().stream()
                .findFirst()
                .map(DashboardReference::getAsOf)
                .orElseGet(LocalDate::now);
        long overdue = invoices.findAll().stream()
                .filter(invoice -> "SENT".equals(invoice.getStatus()))
                .filter(invoice -> invoice.getDueDate().isBefore(asOf))
                .count();
        response.send(new DashboardView(clients.count(), projects.count(), outstanding, overdue));
    }
}

package net.officefloor.hq.app;

import java.math.BigDecimal;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * GET /api/invoices/due?invoiceId=&lt;id&gt; — how much is still left to pay on one invoice after any
 * payments. The amount due is DERIVED: the invoice's amount minus the sum of its payments, computed
 * in {@link BigDecimal} so there is no float drift. Scoped to an invoice (each row asks for its own
 * balance), so the invoice id arrives as a query parameter. Wired by
 * officefloor/rest/api/invoices/due.GET.yml.
 */
public class InvoiceAmountDue {

    public void service(@RequestParam("invoiceId") String invoiceId,
            InvoiceRepository invoices, InvoicePaymentRepository payments,
            ObjectResponse<InvoiceDueView> response) {
        Long id = Long.valueOf(invoiceId);
        BigDecimal amount = invoices.findById(id).map(Invoice::getAmount).orElse(BigDecimal.ZERO);
        BigDecimal paid = payments.findByInvoiceIdOrderByIdAsc(id).stream()
                .map(InvoicePayment::getAmount)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
        response.send(new InvoiceDueView(id, amount.subtract(paid)));
    }
}

package net.officefloor.hq.app;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * GET /api/clients/statement?clientId=&lt;id&gt; — a statement for one client: every invoice across
 * every project the client owns, in id order, each carrying how much is still DUE on it, plus the
 * TOTAL the client still owes (the sum of those dues). Scoped to a client (the statement is for one
 * client), so the client id arrives as a query parameter. The cross-project join and the derived
 * balances live on the server, computed in {@link BigDecimal} so there is no float drift — the same
 * derivation {@link InvoiceAmountDue} applies per invoice. Wired by
 * officefloor/rest/api/clients/statement.GET.yml.
 */
public class GetClientStatement {

    public void service(@RequestParam("clientId") String clientId,
            ProjectRepository projects, InvoiceRepository invoices,
            InvoicePaymentRepository payments,
            ObjectResponse<ClientStatementView> response) {
        Long id = Long.valueOf(clientId);
        List<StatementInvoiceView> rows = new ArrayList<>();
        BigDecimal total = BigDecimal.ZERO;
        // The client owns projects; each project owns invoices. Walk the client's projects (id order)
        // and collect every invoice, so the statement puts them all in one place.
        for (Project project : projects.findByClientIdOrderByIdAsc(id)) {
            for (Invoice invoice : invoices.findByProjectIdOrderByIdAsc(project.getId())) {
                BigDecimal paid = payments.findByInvoiceIdOrderByIdAsc(invoice.getId()).stream()
                        .map(InvoicePayment::getAmount)
                        .reduce(BigDecimal.ZERO, BigDecimal::add);
                BigDecimal due = invoice.getAmount().subtract(paid);
                rows.add(new StatementInvoiceView(invoice.getId(), invoice.getProjectId(),
                        invoice.getStatus(), invoice.getAmount(), due));
                total = total.add(due);
            }
        }
        rows.sort((a, b) -> Long.compare(a.id(), b.id()));
        response.send(new ClientStatementView(id, rows, total));
    }
}
